394	// pushV2Refs pushes v2 checkpoint refs to the target.
395	// Pushes /main, /full/current, and the latest archived generation (if any).
396	// Older archived generations are immutable and were pushed when created.
397	func pushV2Refs(ctx context.Context, target string) {
398		_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2MainRefName))        //nolint:errcheck // pushRefIfNeeded handles errors internally
399		_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2FullCurrentRefName)) //nolint:errcheck // pushRefIfNeeded handles errors internally
400	
401		// Push only the latest archived generation (most likely to be newly created)
402		repo, err := OpenRepository(ctx)
403		if err != nil {
404			return
405		}
406		store := checkpoint.NewV2GitStore(repo, ResolveCheckpointURL(ctx, "origin"))
407		archived, err := store.ListArchivedGenerations()
408		if err != nil || len(archived) == 0 {
409			return
410		}
411		latest := archived[len(archived)-1]
412		_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2FullRefPrefix+latest)) //nolint:errcheck // pushRefIfNeeded handles errors internally
413	}
414	
415	// shortRefName returns a human-readable short form of a ref name for log output.
416	// e.g., "refs/entire/checkpoints/v2/main" -> "v2/main"
417	func shortRefName(refName plumbing.ReferenceName) string {
418		const prefix = "refs/entire/checkpoints/"
419		s := string(refName)
420		if strings.HasPrefix(s, prefix) {
421			return s[len(prefix):]
422		}
423		return s
424	}
